import sys
sys.dont_write_bytecode=True
import audit as a,inspect_revision as v,json,hashlib,pathlib,importlib.util
R=a.ROOT

def main():
 source=a.read(R/'source-analysis.json');stage=a.read(R/'stage-analysis.json');probes=a.read(R/'shortcut-probes.json');cf=a.read(R/'counterfactual-results.json')
 # Resolve coincidental small-subgroup perfect probes using earlier independent opposite-rank seeds rerun on current code.
 controls=a.read(R/'conditional-control-records.json');assert {a.answer(r) for r in controls}=={2,3,4};assert all(not a.check(r)['errors'] for r in controls)
 for p in probes:
  if p['correct']==p['total']:
   assert 'q-73628' in p['subgroup']
   p['conclusion']+=' Current reruns of independent earlier seeds yield ranks 2,3,4 for this same template; this 3/3 coincidence is not a construction invariant.'
   p['sample_refs']+=['conditional-control-records.json','revision-boundaries.json']
 a.save('shortcut-probes.json',probes)
 d=stage['batch_accepted'];assert d['count']==5 and d['rows_minus_one']==2
 assert all(len(set(group['ranks']))>=2 for group in d['groups'])
 var={'learner_operation':source['skill'],
 'fixed_features':[{'feature':'Count pivot columns, with five numeric radio choices.','justification':'All 17 assessed source questions use this task and response contract; the canonical example also asks the count.'},{'feature':'Sparse numeric matrices, short elementary row replacement reduction to REF.','justification':'Tutorial d45a4eba requires REF before identifying pivots; captured assessed sources use one or two row replacements. This preserves moderate workload.'},{'feature':'Source shapes and full bank profiles.','justification':'These bound the observed workload and response domain; fixing the count within them is not justified.'}],
 'answer_roles':[{'role':'Residual rows that vanish or survive after elimination','eligible_variation':'Change zero residual to a later nonzero pivot within fixed shape and workload.','observed':'Controlled rank 2→3 pair; delivered same 3x5 active-three group has ranks 3,3,2, and 4x5 active-four group ranks 4,3.'},{'role':'Pivot locations and dependent row assignment','eligible_variation':'Vary ordered pivot columns, prefix sources and active rows while preserving a short valid elimination.','observed':'Fresh normal samples cover every retained template; current branch uses explicit compatible rank/active assignments without changing elimination validity.'},{'role':'Matrix labels and correct choice positions','eligible_variation':'Rename matrices and shuffle the full bank independently.','observed':'Name counterfactual preserves matrix/rank; label, first-choice and bank-extreme probes have counterexamples. Small finite subgroup coincidences are documented.'}],
 'coverage':[{'case':'Exact runner batch after preparation','sample_refs':['batch.json','delivery-batch/accepted.json','stage-analysis.json'],'result':'5/5 survive; ranks 2,3,4; both selected shape/active-row groups contain contrasting outcomes.'},{'case':'All 17 source workload/bank profiles and fresh normal samples','sample_refs':['source-replays.json','coverage.json','samples.json','author-check/regression-controls.json','author-check/regression-results.json'],'result':'17 complete source replays and 51 fresh normal samples pass independent exact checks. Author checker rerun supplies two contrasting ranks for every source workload; fresh independent batch seeds and counts also pass.'},{'case':'Retained defect is real and current revision changes its result','sample_refs':['prior-failing-batch.json','shortcut-regression-runs.json','fresh-batch-69137.json'],'result':'Strict original shortcut test exits 1 on old 5/5 failing pool and 0 on current batch. Relocated author assertion also fails on the old pool, then passes against current code.'}],
 'counterfactuals':[{'kind':'relevant','change':'At fixed q-130957 parameters and seed 74109, change final residual row entry (3,5) from 0 to 1; exactly one input matrix cell changes.','expected':'Rank, selected numeric key and solution conclusion change from 2 to 3; prompt retains all other matrix entries. Native grader swaps acceptance of choices 2 and 3.','observed':'Independent exact ranks 2 and 3; prompt/solution stages agree; both rendered prompts show the one-cell difference. Native grader accepts 2 only before and 3 only after, rejecting the opposite choice.','status':'passed','justification':'The necessary operation is deciding whether elimination leaves a nonzero row; source f1ae8763 and 8a6c1395 demonstrate both outcomes.','sample_refs':['counterfactual-records.json','counterfactual-results.json','grader-input.json','grader-results.json','render/rendering.json','render-rest/rendering.json']},{'kind':'irrelevant','change':'Rename matrix A to D with all matrix data fixed; separately rescale a nonzero echelon prefix row before reversing the fixed operations.','expected':'Rank remains 3; names update throughout prompt and explanation; keys still select 3, native grading preserves numerical choice acceptance.','observed':'Matrices identical under rename, names updated in rendered prompt/solution; rank unchanged under both irrelevant changes. Native grader accepts 3 and rejects all four alternatives for each.','status':'passed','justification':'Matrix names and invertible row rescaling do not alter pivot count; labels are incidental in all captured questions.','sample_refs':['counterfactual-records.json','counterfactual-results.json','grader-input.json','grader-results.json','render-rest/rendering.json']}],
 'shortcut_probes':probes,
 'delivery':{'stages_examined':['normal construction validity and new forced-decision branch','batch rank/active assignment and semantic dedup retry','actual shared publication normalization and inventory/within-batch deduplication','requested moderate difficulty filter','captured inventory and read-only learner weighted selection scenarios'], 'sample_refs':['delivery-batch/delivery.json','delivery-batch/accepted.json','delivery-samples/delivery.json','stage-analysis.json','shortcut-regression-runs.json','batch-replay.json'], 'result':'At captured basis 5362, batch survives 5/5 and normal controls 51/51 with identical ranks and choice semantics. No preparation file exists; shared tool runs actual prepare_records. Weighted moderate selection retains eligible contrasts; explicit history-subset scenarios are recorded, not asserted to be live histories.'},
 'limitations':['No finite review proves absence of every incidental shortcut.','Source canonical example has no captured answer-control evidence; all 17 assessed source cases replayed, canonical mathematics confirmed.','Live selection policy, actual learner histories and future inventory/entity IDs are not captured. Hypothetical scenarios use explicitly synthetic IDs. Exhausted subsets can lose contrasts.','A three-sample q-73628 coincidence was challenged using independent prior seeds rerun on current code; ranks 2,3,4 remain available.','Captured inventory lacks generated metadata; no affected stored defect demonstrated and no generated identity invented.']}
 a.save('pedagogical-variation.json',var)
 inspected=['render/question-003.png','render/question-006.png','render-rest/question-001.png','render-rest/question-006.png']
 a.save('render-inspection.json',{'renderer':'unmodified UI via render_preview.py','reports':['render/rendering.json','render-rest/rendering.json'],'automated_records':12,'visually_inspected_screenshots':inspected,'observations':'Readable matrices, all five radio controls, row replacement annotations, intermediate matrices and conclusions; no clipping in inspected one-operation, controlled rank-2/rank-3, and six-column examples. Renderer reports no math/JS/image errors in all twelve.','counterfactual_visual_relationship':'render/question-006 versus render-rest/question-001: one input cell changes 0 to 1, final zero row becomes nonzero, selected value and explanation change 2 to 3. Later rest cases show rename and rescale.'})
 before=a.read(R/'package-tree-before.json');after={str(p.relative_to(a.PKG)):hashlib.sha256(p.read_bytes()).hexdigest() for p in a.PKG.rglob('*') if p.is_file()};assert before==after
 a.save('package-tree-after.json',after)
 old=a.JOB/'review-0-policy-2-aac6b6dace0e282d/relocated-package';unchanged={n:(old/n).read_bytes()==(a.PKG/n).read_bytes() for n in ['math_format.py','requirements.txt','source-data.json']}
 a.save('unchanged-runtime-evidence.json',{'unchanged_files':unchanged,'reused_prior_control':'prior-samples.json plus prior-math-results.json; original source binding matches and item-construction diff is retained in package-diff.patch','generator_changes':'new optional forced decision argument; batch assembly groups contrasting residual outcomes; old independent generate path preserved.'})
 assert all(unchanged.values())
 math=a.read(R/'math-results.json');assert not math['failures'];replay=a.read(R/'source-replay-results.json');assert len(replay['cases'])==17 and not replay['excluded'];assert all(all(c[x] for x in ['source_matrices_equal','complete_bank_equal','source_key_equal']) and not c['errors'] for c in replay['cases'])
 for n in ['render/rendering.json','render-rest/rendering.json']:assert a.read(R/n)['passed']
 pkg=a.read(R/'packaging-results.json');assert pkg['python']=='3.13.5' and pkg['packages']=={'sympy':'1.14.0'} and pkg['relocation_and_deterministic_match'] and pkg['explicit_parameter_replay']
 a.save('commands.json',{'python':str(a.PY),'cwd':str(R),'commands':['python -B audit.py','python -B retained_repair_checks.py','python -B inspect_revision.py','python -B check_batch_shortcut.py --input prior-failing-batch.json # expected exit 1','python -B check_batch_shortcut.py --input batch.json # expected exit 0',f'python -B {a.REPO}/generate/pipeline/check_delivery.py --input batch.json --source ../source/source.json --inventory ../source/inventory.json --difficulty moderate --output delivery-batch --asset-root ../workspace --math-root /media/jake/SSD/EDB/math',f'python -B {a.REPO}/generate/pipeline/check_delivery.py --input samples.json --source ../source/source.json --inventory ../source/inventory.json --difficulty moderate --output delivery-samples --asset-root ../workspace --math-root /media/jake/SSD/EDB/math',f'{a.REPO}/generate/runs/current/check-engine grader-input.json grader-results.json',f'python -B {a.REPO}/generate/pipeline/render_preview.py --input render-input.json --output render --asset-root ../workspace --math-root /media/jake/SSD/EDB/math',f'python -B {a.REPO}/generate/pipeline/render_preview.py --input render-rest-input.json --output render-rest --asset-root ../workspace --math-root /media/jake/SSD/EDB/math','python -B finalize_review.py']})
 def passed(paths,details):return {'status':'passed','evidence_paths':paths,'details':details}
 result={'verdict':'accepted','summary':'The retained batch shortcut is repaired. All eight checks pass, with no demonstrated current defect. Package files remain unchanged.','source_analysis':{k:source[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']},'checks':{
 'source_replay':passed(['source-analysis.json','source-replay-results.json','source-replays.json'],'All 17 assessed sources reproduce matrices, stages, complete banks and keys; canonical answer-control evidence is absent and recorded.'),
 'math':passed(['math-results.json','delivered-content-comparison.json'],'Exact prompt ranks, displayed row operations, REF and conclusions pass on 77 source/sample/batch/counterfactual records and all five normalized delivered records.'),
 'variety':passed(['coverage.json','stage-analysis.json','shortcut-regression-runs.json','author-check/regression-results.json'],'Current batch varies rank in each selected shape/active-row group. Every source workload remains supported; new assembly passes retained and fresh-seed regressions.'),
 'scope':passed(['source-analysis.json','pedagogical-variation.json','unchanged-runtime-evidence.json'],'Changes preserve numeric pivot-count questions, full five-choice profiles and comparable short elementary elimination workload.'),
 'grading':passed(['grader-input.json','grader-results.json'],'Native grader accepts 26 exact-rank selections and rejects 104 distractors, including relevant/irrelevant controlled pairs and delivered records. This radio contract has no free-entry notation surface.'),
 'rendering':passed(['render/rendering.json','render-rest/rendering.json','render-inspection.json'],'Twelve records render through the actual UI; representative screenshots inspected, including controlled outcomes and widest source matrices.'),
 'packaging':passed(['packaging-results.json','revision-boundaries.json','batch-replay.json','package-tree-before.json','package-tree-after.json'],'Exact installed dependency strings match; relocation, deterministic replay, external output, valid boundary and invalid-input checks pass. Full package tree is unchanged.'),
 'decision_variation':passed(['pedagogical-variation.json','stage-analysis.json','shortcut-regression-runs.json','affected-inventory.json','inventory-assessment.json'],'Old batch still fails strict shortcut regression; revised delivered batch scores only 2/5 on rows-minus-one and contains same-shape contrasts. Controlled dependence and label changes pass actual grading/rendering. Captured inventory inspected without demonstrated affected records.')},'findings':[]}
 a.save('result.json',result)
 # Evidence-contract checks: strict schema plus every final evidence path and nested sample ref must exist.
 import subprocess
 subprocess.run(['python3','-B','-c','import json,jsonschema,sys; jsonschema.validate(json.load(open(sys.argv[1])),json.load(open(sys.argv[2])))',str(R/'pedagogical-variation.json'),str(a.REPO/'generate/pipeline/pedagogical-variation.schema.json')],check=True,capture_output=True,text=True)
 refs=[]
 def walk(x):
  if isinstance(x,dict):
   for k,z in x.items():
    if k in ('sample_refs','evidence_paths'):refs.extend(z)
    else:walk(z)
  elif isinstance(x,list):
   for z in x:walk(z)
 walk(var);walk(result)
 for path in refs:
  p=R/path;assert not pathlib.Path(path).is_absolute() and p.is_file() and p.stat().st_size>0,path
 a.save('evidence-validation.json',{'pedagogical_schema':'passed','nonempty_relative_evidence_references':len(refs),'all_eight_checks_passed':len(result['checks'])==8,'package_tree_unchanged':True})
 (R/'session-state.md').write_text('Review complete: accepted. Source account confirmed before package reads. Retained defect reproduced on old pool and repaired on current delivered batch. All eight checks have evidence, including 17 source replays, 51 fresh normal samples, exact batch, controlled pairs, 130 native grading checks, 12 actual-UI renders and screenshot inspection. Captured basis 5362 inventory checked for retained defect; none demonstrated. Full package tree unchanged. result.json and pedagogical-variation.json saved; schema and nonempty relative evidence references validated.\n')
 print(json.dumps({'verdict':result['verdict'],'checks':len(result['checks']),'findings':0,'schema':'passed','references':len(refs),'package_unchanged':True}))
if __name__=='__main__':main()
